window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"G2rcIQGsH_s","speaker":"Bassirou Diomaye Diakhar Faye","role":"President","country":"Senegal","region":"Africa","url":"https://www.youtube.com/watch?v=G2rcIQGsH_s","date":"20260924","title":"🇸🇳 Senegal - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":798,"words":1603,"counts":{"claims":18,"promises":6,"attacks":0},"topics":[{"topic":"UN governance","share":0.2477,"seconds":198},{"topic":"UN diplomacy","share":0.0944,"seconds":75},{"topic":"Israel-Palestine conflict","share":0.0898,"seconds":72},{"topic":"UN leadership","share":0.0876,"seconds":70},{"topic":"UN legitimacy","share":0.0842,"seconds":67},{"topic":"Sahel security","share":0.0834,"seconds":67},{"topic":"UN performance","share":0.0812,"seconds":65},{"topic":"Climate change","share":0.0781,"seconds":62},{"topic":"Senegal technology","share":0.078,"seconds":62},{"topic":"Sports development","share":0.0758,"seconds":60}],"timeline":[[5,80,"UN diplomacy"],[83,156,null],[159,226,"UN legitimacy"],[227,298,"Israel-Palestine conflict"],[301,367,"Sahel security"],[368,430,"Climate change"],[432,494,"Senegal technology"],[494,559,"UN performance"],[560,624,"UN governance"],[625,688,"UN governance"],[689,760,"UN governance"],[761,831,"UN leadership"],[833,893,"Sports development"],[896,921,null]],"stances":{"UN diplomacy":"The speaker thanks the predecessor and extends wishes for success to the current President of the General Assembly.","UN legitimacy":"Bassirou Diomaye Diakhar Faye states that there is a crisis of confidence in international institutions, international law, and the original promise of the United Nations, while noting that armed conflicts are increasing globally.","Israel-Palestine conflict":"Bassirou Diomaye Diakhar Faye asserts that the situation in Gaza and the OPT involves unconscionable human suffering and systemic violations of international law, requiring immediate action to halt mass murder and destruction.","Sahel security":"Bassirou Diomaye Diakhar Faye states that the fight against terrorism in the Sahel must be a common struggle and that he will work to bring peace and security in the sub-region.","Climate change":"Bassirou Diomaye Diakhar Faye states that climate urgency has become a bitter reality and calls for action on all fronts.","Senegal technology":"Bassirou Diomaye Diakhar Faye states that Senegal supports the development of artificial intelligence grounded in ethical principles and highlights the launch of a satellite as evidence of this commitment.","UN performance":"Bassirou Diomaye Diakhar Faye argues that despite challenges, the UN must be strengthened rather than abandoned in favor of isolation.","UN governance":"Bassirou Diomaye Diakhar Faye argues that UN reform must reduce bureaucracy and increase agility to ensure a just international order.","UN leadership":"Bassirou Diomaye Diakhar Faye expresses support for Maki Sal's candidacy and calls for a UN that builds bridges rather than walls.","Sports development":"Bassirou Diomaye Diakhar Faye states that Senegal will host the first Olympic event in Africa to foster unity and build a generation that comes together rather than stands apart."},"claims":[{"t":212,"quote":"And yet armed conflicts are increasing in number. war in wars in Ukraine, the Middle East, Sudan, Haiti, Yemen, and Africa, including the expansion of terrorism in the Sahel.","topic":"UN legitimacy","kind":"fact"},{"t":227,"quote":"All of these bear witness to the continued worsening and deep cracks in international peace and security in Gaza and indeed throughout the OPT, human suffering is unconscionable.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":250,"quote":"The systemic there are systemic violations of international law and these are unacceptable.","topic":"Israel-Palestine conflict","kind":"fact"},{"t":302,"quote":"the fact that there is an arms race in outer space in this cont context","topic":"Sahel security","kind":"fact"},{"t":350,"quote":"the scourge of terrorism is crossborder by its very nature","topic":"Sahel security","kind":"fact"},{"t":372,"quote":"The Ebola ep epidemic is an example of just that.","topic":"Climate change","kind":"fact"},{"t":376,"quote":"Global inequalities are increasing.","topic":"Climate change","kind":"fact"},{"t":466,"quote":"The launch of our first satellite illust illustrates our desire to make space AI and the digital and digital tools instruments that serve and foster human development.","topic":"Senegal technology","kind":"fact"},{"t":508,"quote":"The implementation of these is lagging behind and significantly so.","topic":"UN performance","kind":"fact"},{"t":560,"quote":"We will not achieve peace if we simply stage power struggles.","topic":"UN governance","kind":"fact"},{"t":576,"quote":"Doing all of that will imperel the very reset of our organization.","topic":"UN governance","kind":"fact"},{"t":636,"quote":"We've used our own resources to build a UN house some 30 kilometers away from This is a cuttingedge institution and the site will house all UN system in the region","topic":"UN governance","kind":"fact"},{"t":689,"quote":"We all agree that the composition of the security council is out of step with the realities of our time.","topic":"UN governance","kind":"fact"},{"t":737,"quote":"Sagal is presenting its candidacy to a non-permanent seat on the Security Council for two 2032 2033.","topic":"UN governance","kind":"fact"},{"t":770,"quote":"That is the vision embraced and espoused by Maki Sal, former president of the Republic of Senagal.","topic":"UN leadership","kind":"fact"},{"t":841,"quote":"This is the first Olympic event in history to be held in Africa.","topic":"Sports development","kind":"fact"},{"t":844,"quote":"It will be held from the 31st of October to the 13th of November.","topic":"Sports development","kind":"number"},{"t":851,"quote":"It will welcome athletes from 206 National Olympic communities.","topic":"Sports development","kind":"number"}],"promises":[{"t":325,"quote":"I will spare no effort to work to bring peace and security in the sub region","topic":"Sahel security","kind":"promise"},{"t":399,"quote":"That is our ambition for the third United Nations water conference that Sagal will co-organize with the United Arab Emirates. It will be held this year.","topic":"Climate change","kind":"promise"},{"t":552,"quote":"We will not settle crisis by allowing the multilateral system to become ever more peacemeal.","topic":"UN performance","kind":"promise"},{"t":613,"quote":"It must remove red tape, make it more agile and make it more effective in its expenditure.","topic":"UN governance","kind":"promise"},{"t":619,"quote":"And there must be better synergies between headquarters on the field so we can better serve the people we represent.","topic":"UN governance","kind":"promise"},{"t":868,"quote":"We will host a generation that wish to come together rather than stand apart.","topic":"Sports development","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":5,"topic":"UN diplomacy","text":"The assembly will now hear an address from his excellency Mr. Basuay Dakari, President of the Republic of Senagal. &gt;&gt; I request protocol to accompany his I invite him to address the assembly. Mr. the President of the General heads of State and Government, Secretary General, Ministers, distinguished delegates, President on behalf of Senagal, I wish to thank your predecessor and convey to you my hearty I also wish you every success as you steer the work of the 81st session of the United Nations General Assembly."},{"t":83,"topic":null,"text":"Moreover, I wish to once again reiterate our unwavering support for Secretary General Antonio Gutierrez's work in service of peace, development, and human rights. We commend his conduct of the organization and we wish him every success in his future endeavors once his mandate concludes. Dear colleagues, as was the case last year, we are yet again meeting here in against the backdrop of a worrying global juncture. The organization is facing an unprecedented accumulation of complex global challenges. Against that the theme of this session rightly expresses the fact that we are facing a major issue. Indeed, the major issue of our time is restoring trust, managing transformation in order to build a united nations that delivers for The current crisis we face is undoubtedly a crisis of trust."},{"t":159,"topic":"UN legitimacy","text":"More trust between states needs to come about. But there is a crisis in that trust. There's a crisis of confidence and trust in international institutions. And there's a crisis of confident confidence rather in international law's ability to enforce agreements reached on the basis of the United Nations charter. Finally, there is a crisis of confidence in the original promise of the United Nations, namely preserving succeeding generations from the scourge of war and promoting economic social progress for It is high time to once again place this promise at the heart of the UN's work. If we do not wish it to remain a dead ideal, it must become once more a reality for everyone. And yet armed conflicts are increasing in number. war in wars in Ukraine, the Middle East, Sudan, Haiti, Yemen, and Africa, including the expansion of terrorism in the Sahel."},{"t":227,"topic":"Israel-Palestine conflict","text":"All of these bear witness to the continued worsening and deep cracks in international peace and security in Gaza and indeed throughout the OPT, human suffering is unconscionable. The systemic there are systemic violations of international law and these are unacceptable. It is high time to act to halt the horror of mass murder and destruction. No country, no sec, no peace, no security can be viable, nor can it last without the two-state solution. Palestine with East Jerusalem as its capital and Israel. The two living side by side with in safe and internationally recognized borders in a in a situation of ongoing conflict which favors an arms race which erodess disarmament mechanisms and fuels risk linked to new technologies."},{"t":301,"topic":"Sahel security","text":"and that the the fact that there is an arms race in outer space in this cont context we call for a collective stirring peaking of our conscience. Peace is not a simple aspiration. It cannot be. It is a collective responsibility. It is for this reason that as interim president of si echoas I will spare no effort to work to bring peace and security in the sub region. Of course I will be doing this alongside the African Union and the United Nations working closely with them. I am now thinking specifically here of the fight against terrorism. It must be a common struggle because the scourge of terrorism is crossborder by its very nature. The Sahel must not be abandoned to its desolate fate. Its stabil must be pursued."},{"t":368,"topic":"Climate change","text":"It cannot be forgotten. Of course, there are worsening health crises. The Ebola ep epidemic is an example of just that. Global inequalities are increasing. Climate the climate urgency has become an even more bitter reality. The human e and economic and social cost of these b of these phenomenon continue to grow. There are many environmental perils facing our age. We need to act on all fronts. That is our ambition for the third United Nations water conference that Sagal will co-organize with the United Arab Emirates. It will be held this year. Ladies and gentlemen, a lasting peace cannot be decoupled from 40 years after the adoption of the Declaration on the Right to development, we know what we need to do to achieve that goal. There needs to be a wholesale reform of international financial architecture."},{"t":432,"topic":"Senegal technology","text":"There needs to be sustainable debt. There needs to be equitable taxation and better access to concessional financing. There also needs to be the implementation of the severe commitment as well as of the pact for the future. Senagal also believes in the transformative potential of new technologies, including the development of AI that is based on robust morals and ethical code based on the principle of responsibility and inclusion. The launch of our first satellite illust illustrates our desire to make space AI and the digital and digital tools instruments that serve and foster human development. President, dear colleagues, we are all well aware of the challenges linked to the very life of our organization. Ours is a concerning financial situation."},{"t":494,"topic":"UN performance","text":"It's affecting the UN's operational capacity and that is prompting questions about how effective the UN really is. Indeed, these questions are being asked about peace operations just as they are about the SDGs. The implementation of these is lagging behind and significantly so. In view of this reality, it is true that some might be tempted to view multilateralism as a relic and might be tempted to move outside of n of multilateralism to take action in isolation. Senagal does not espouse that view. On the contrary, it is precisely because the world is beset by a whole host of unprecedented crises that we need a UN that is stronger, more representative, and more effective. We will not settle crisis by allowing the multilateral system to become ever more peacemeal."},{"t":560,"topic":"UN governance","text":"We will not achieve peace if we simply stage power struggles. We will not guarantee a just international order if we ensure that if we see might being right being replaced by might. Doing all of that will imperel the very reset of our organization. That is dialogue, conflict prevention, the peaceful resolution of disputes, cooperation and respect for international law. In this vein and with this in mind, the UN80 initiative provides us with a historic opportunity to usher in the structural and normative transformations that we need to see. However, reforming the United Nations must not styy its ambitions. On the contrary, it must make it less bureaucratic in how it functions. It must remove red tape, make it more agile and make it more effective in its expenditure. And there must be better synergies between headquarters on the field so we can better serve the people we represent."},{"t":625,"topic":"UN governance","text":"Senagal supports that very dynamic. That was the rationale behind our contribution to efforts to strengthen the UN system. We've used our own resources to build a UN house some 30 kilometers away from This is a cuttingedge institution and the site will house all UN system in the region and that will foster greater coherence and effectiveness in the UN's work. However, a stronger organization and ensuring it is stronger also involves member states upholding their financial contri pledges and making good on their assessed contributions. President, the years are ticking by, but our efforts to reform governance have yet to produce a significant impact. The status quo when it comes to reforming the security council bears witness to that fact."},{"t":689,"topic":"UN governance","text":"We all agree that the composition of the security council is out of step with the realities of our time. We agree that the expansion of the council should not lead to further inertia. But given the fact the council is lacking legitimacy and that is indeed the hallmark of the council's current structure, we cannot simply issue observations. We are in at a juncture where there is an urgent need for action. It's a matter of justice, credibility and balance across the international system. And this is indeed the rationale which underpins the Ezelwini consensus which outlines the African position in connection with the so necessary reform of the UN security council. In that vein, Sagal is presenting its candidacy to a non-permanent seat on the Security Council for two 2032 2033. However, beyond reform, the organization also needs experienced leadership to steer its work in these times of crisis and uncertainty."},{"t":761,"topic":"UN leadership","text":"The UN needs a secretary general able to speak to one and all, able to listen and to build bridges between member states. That is the vision embraced and espoused by Maki Sal, former president of the Republic of Senagal. Here I wish once again to express my support for his candidacy. I wish to reiterate Sagal's request that you as member states support his candidacy. Ladies and gentlemen, at a time when our organization is seeking to rebuild trust, Sagal continues to believe in the vision of a world based on peace, justice, the dignity of each and every human being and human The world does not need unilateral posturing. It needs a fairer, more inclusive and more effective Addressing our challenges requires bridges and not walls, dialogue and not cooperation and not isolation, law and not might."},{"t":833,"topic":"Sports development","text":"That is the very spirit in which Sen Sagal will host the youth Olympic games in Dhaka 2026. This first, this is the first Olympic event in history to be held in Africa. It will be held from the 31st of October to the 13th of November. It will welcome athletes from 206 National Olympic communities. It will welcome young people from across the world. And in doing just that, Senagal will do much more than host a sporting sporting competition. It will host a We will host a generation that wish to come together rather than stand apart. One that wishes to build together rather than pit themselves against each other. That is our promise to those young people and it is the Olympic promise and ultimately that is the promise of the United Nations. That is making strength out of our differences, make making wealth out of our diversity and making our human community the very bedrock of peace."},{"t":896,"topic":null,"text":"In that Olympic spirit, I invite all member states to attend the opening ceremony of the youth games on the 31st of October 2026 in Dhaka. And I thank you for your kind attention assembly. On behalf of the assembly, I wish to thank the president of the Republic of Sagal."}],"compare":[{"topic":"UN & its reform","share":0.5951,"mean":0.2027,"rank":1,"others":170},{"topic":"Israel–Palestine","share":0.0898,"mean":0.0522,"rank":43,"others":76},{"topic":"Africa","share":0.0834,"mean":0.0231,"rank":23,"others":36},{"topic":"Climate Change","share":0.0781,"mean":0.0426,"rank":45,"others":77},{"topic":"Youth","share":0.0758,"mean":0.0021,"rank":3,"others":5}]};
